{% doc %}
  Fulldev UI video styles. Use native markup with its data-slot parts.
{% enddoc %}

{{ 'ui-video.css' | asset_url | stylesheet_tag }}

/* The playing media of a video: a Shopify video, an embed, or the click-to-load cover that becomes
   one. It fills its aspect-ratio frame, which carries Fulldev UI's border and radius. */
[data-slot='video'] {
  display: block;
  width: 100%;
  height: 100%;
  border: 0;
  background: var(--muted);
  object-fit: cover;
}
